MAX_IN_FLIGHT = 4
slots = asyncio.Semaphore(2)
in_flight = 0

@app.get("/r")
async def r():
    global in_flight
    if in_flight >= MAX_IN_FLIGHT:
        return JSONResponse(
            status_code=503,
            headers={"Retry-After": "1"},
            content={"detail": "busy"},
        )
    in_flight += 1
    try:
        async with slots:
            await asyncio.sleep(0.05)   # the work
            return {"ok": True}
    finally:
        in_flight -= 1

